var PusherClient=new function(){let mThis=this;this.branch_id=$('meta[name="sess_branch_id"]').attr('content');this.user_id=$('meta[name="sess_user_id"]').attr('content');this.current_view_name='';this.backend_channel_name=['vsmclinic.backend.',this.branch_id].join('');this.pusher_channel={'bind':()=>{return;}};let pusher_app_key='b7351506ee87f3eec932';let pusher=new Pusher(pusher_app_key,{cluster:'mt1',useTLS:true,disableStats:true,authorizer:function authorizer(channel,options){return{authorize:function authorize(socketId,callback){let p={"socket_id":socketId,"channel_name":channel.name};vsapi.call(`${main_view.base_url}/api/broadcast/auth`,p).then(auth_data=>{console.log('Pusher authorization succeeded!');callback(null,auth_data);});}};}});pusher.connection.bind('connected',(payload)=>{console.info('Web socket connection successful :)');});mThis.pusher_channel=pusher.subscribe(`private-${mThis.backend_channel_name}`);mThis.pusher_channel.bind('pusher:subscription_succeeded',(d)=>{console.info("Channel subscription succeeded");});mThis.pusher_channel.bind('pusher:subscription_error',(d)=>{console.error("Channel subscription error: "+d);});mThis.pusher_channel.bind('appointment_created',d=>{let data=d.data;Swal.fire({position:'top-end',icon:'success',title:data.message,toast:true,showConfirmButton:false,timer:2000,showClass:{popup:'animate__animated animate__fadeInDown'},});let order_id=data.order?data.order.id:0;let image_count=(data.order||{}).image_count;OrderImagesComponent.addImage(order_id,data.img,image_count);});mThis.pusher_channel.bind('payment_received',d=>{let data=d.data;Swal.fire({position:'top-end',icon:'success',title:data.message,toast:true,showConfirmButton:false,timer:2000,showClass:{popup:'animate__animated animate__fadeInDown'},});let order_id=data.order_id;OrderImagesComponent.removeImage(order_id,data.image_id,data.image_count);});mThis.pusher_channel.bind('message_received',function(data){Swal.fire({position:'top-end',icon:'success',title:JSON.stringify(data),toast:true,showConfirmButton:false,timer:2000,showClass:{popup:'animate__animated animate__fadeInDown'},});});}